CREATE TABLE IF NOT EXISTS  dm_otc_n.bi_otc_swap_trd_stat( 
	 company_name string COMMENT '公司名称' , company_id string COMMENT '公司ID' , time_period string COMMENT '时间区间（近一年/历史）' , weekly_trd_freq string COMMENT '每周交易频率(笔)' , avg_trd_amount string COMMENT '单笔平均交易规模' , trd_win_rate string COMMENT '交易胜率' , yield_rate string COMMENT '收益率' , swap_first_trd_type string COMMENT '互换业务笔数第一业务类型' , swap_second_trd_type string COMMENT '互换业务笔数第二业务类型' , swap_first_trd_count string COMMENT '互换业务第一交易笔数' , swap_second_trd_count string COMMENT '互换业务第二交易笔数' ) COMMENT 'OTC互换交易统计表' PARTITIONED BY ( busi_date string COMMENT '业务日期' ) STORED AS ORC;
